import faiss
from sentence_transformers import SentenceTransformer

qa_data = {
    "奥司他韦是治什么的？": """奥司他韦是一种抗流感病毒药物，主要用于甲型流感和乙型流感的治疗，也可用于特定场景下的流感预防。它属于神经氨酸酶抑制剂，作用靶点是流感病毒表面的神经氨酸酶，可以减少新生成的病毒颗粒从宿主细胞释放，从而降低病毒在呼吸道内继续扩散的能力。""",
    "神经氨酸酶抑制剂是什么？": """神经氨酸酶抑制剂是一类常见的抗流感病毒药物，主要通过抑制流感病毒表面的神经氨酸酶发挥作用。流感病毒复制后需要借助神经氨酸酶从被感染细胞表面释放出来，继续感染其他细胞；这类药物会阻断这一过程。常见代表包括奥司他韦、扎那米韦和帕拉米韦。""",
    "玛巴洛沙韦和奥司他韦有什么区别？": """玛巴洛沙韦和奥司他韦都可用于流感抗病毒治疗，但作用机制不同。奥司他韦是神经氨酸酶抑制剂，主要影响病毒从宿主细胞释放的过程；玛巴洛沙韦作用于流感病毒复制早期的 cap-dependent endonuclease，主要干扰病毒 RNA 转录。两者都针对流感病毒，但药理靶点并不相同。""",
    "感冒和流感有什么区别？": """普通感冒和流感都会引起咳嗽、流鼻涕、鼻塞、咽痛等呼吸道症状，但流感通常起病更急，全身症状更明显。普通感冒多由鼻病毒等引起，症状一般较轻；流感由流感病毒引起，常见表现包括高热、寒战、头痛、肌肉酸痛和明显乏力，传染性、季节性和并发症风险通常更突出。""",
    "抗生素能治疗流感吗？": """抗生素主要用于治疗细菌感染，不能直接治疗流感病毒感染。抗生素的作用对象通常是细菌的细胞壁、蛋白质合成、核酸代谢等结构或过程，而流感病毒没有这些典型细菌结构。流感属于病毒感染，针对病毒本身通常依赖抗病毒药物或免疫系统清除，而不是抗生素。""",
    "疫苗为什么能预防疾病？": """疫苗通过让免疫系统提前接触病原体的关键特征来建立保护，例如病毒蛋白、细菌抗原或编码抗原的信息。接种后，人体可以产生特异性抗体、T 细胞反应和免疫记忆。以后遇到相同或相似病原体时，免疫系统能够更快识别并启动反应，从而降低感染、重症或传播风险。""",
    "PCR检测是什么？": """PCR 是聚合酶链式反应，是一种扩增特定核酸片段的分子生物学技术。它通过反复进行变性、退火和延伸，把样本中很少量的 DNA 或 RNA 相关序列复制成大量拷贝，使检测设备更容易识别目标片段。PCR 常用于病原体检测、遗传分析、肿瘤相关检测、法医学鉴定和基础科研。""",
    "DNA和RNA有什么区别？": """DNA 和 RNA 都是核酸，但结构、成分和功能不同。DNA 通常是双链结构，主要负责长期储存遗传信息；RNA 通常是单链结构，更多参与遗传信息传递、基因表达调控和蛋白质合成。组成上，DNA 使用脱氧核糖和碱基 T，RNA 使用核糖和碱基 U。""",
    "为什么会发烧？": """发烧是人体对感染、炎症或其他刺激产生的体温调节反应。免疫细胞识别病原体或组织损伤信号后，会释放细胞因子等炎症介质，这些信号影响下丘脑的体温调定点，使身体通过寒战、血管收缩和代谢变化升高体温。发热本质上是免疫反应和体温调节共同作用的结果。""",
    "病毒和细菌有什么区别？": """病毒和细菌都是常见病原体，但生物学特征差异很大。细菌是具有细胞结构的单细胞生物，通常可以独立代谢和繁殖；病毒没有完整细胞结构，必须进入宿主细胞后利用宿主细胞的物质和系统复制自己。抗生素主要针对细菌，抗病毒药物则通常针对病毒进入、复制、释放等环节。""",
    "免疫系统是怎么工作的？": """免疫系统由免疫器官、免疫细胞和多种信号分子组成，主要负责识别并清除病原体、异常细胞和外来物质。先天免疫反应速度快，提供第一道防线；适应性免疫反应更有针对性，可以产生抗体、T 细胞反应和免疫记忆。两者协同工作，使人体能够应对感染、损伤和异常细胞变化。""",
    "过敏反应是什么？": """过敏反应是免疫系统对某些通常无害的物质产生过度反应的现象，这些物质称为过敏原，例如花粉、尘螨、动物皮屑、食物成分或药物分子。过敏时，免疫细胞会释放组胺等炎症介质，引起打喷嚏、流鼻涕、皮疹、瘙痒、咳嗽、气道收缩或消化道不适等表现。""",
    "炎症是什么？": """炎症是机体面对感染、损伤或刺激时产生的防御性反应。典型过程包括局部血管扩张、血流增加、血管通透性升高、免疫细胞聚集和炎症介质释放。炎症可以帮助清除病原体、移除受损细胞并启动组织修复，常见表现包括红、肿、热、痛和功能受限。""",
    "血糖高是什么意思？": """血糖高是指血液中的葡萄糖浓度超过正常范围。葡萄糖是人体重要能量来源，主要来自食物中的碳水化合物，并受胰岛素、胰高血糖素、肝糖原分解和组织摄糖能力等因素调节。血糖升高可能与进食、应激、运动不足、胰岛素分泌不足或胰岛素抵抗有关。""",
    "高血压是什么意思？": """高血压是指动脉血管内压力长期处于较高水平。血压由心脏泵血能力、血管弹性、血容量和外周血管阻力共同决定。长期血压偏高会增加心脏、脑、肾脏、眼底和血管系统负担，常与遗传、年龄、饮食、体重、运动、精神压力和代谢状态有关。""",
    "蛋白质在人体里有什么作用？": """蛋白质是人体重要的生物大分子，由氨基酸组成，具有结构支撑、酶催化、物质运输、免疫防御、信号传递和肌肉收缩等多种功能。许多酶、抗体、受体、转运蛋白、细胞骨架成分和部分激素都属于蛋白质。蛋白质的功能取决于氨基酸序列、空间结构和细胞环境。""",
    "光合作用是什么？": """光合作用是植物、藻类和部分细菌利用光能合成有机物的过程。植物叶绿体中的叶绿素吸收太阳光能，将二氧化碳和水转化为葡萄糖等有机物，并释放氧气。光合作用为植物自身提供物质和能量基础，也为生态系统提供有机碳来源，并维持大气氧气的重要来源。""",
    "为什么天空是蓝色的？": """天空呈蓝色主要与瑞利散射有关。太阳光看起来接近白色，实际包含多种波长的可见光。太阳光进入地球大气后，短波长的蓝光比长波长的红光更容易被空气分子散射到各个方向。人从地面看向天空时，看到的是来自各方向的蓝色散射光。""",
    "温室效应是什么？": """温室效应是指大气中的某些气体吸收地表释放的红外辐射，并把部分热量重新辐射回地表和低层大气的现象。水蒸气、二氧化碳、甲烷和氧化亚氮都是重要温室气体。适度温室效应使地球保持较适宜温度，温室气体浓度增加则会改变地球能量平衡。""",
    "地震是怎么发生的？": """地震通常与地壳岩石中的应力积累和突然释放有关。地球岩石圈由多个板块组成，板块之间会发生碰撞、拉张或错动。当断层附近岩石承受的应力超过强度极限时，岩层会突然破裂或滑动，释放出的能量以地震波形式向外传播，地面因此出现震动。""",
    "火山为什么会喷发？": """火山喷发通常由地下岩浆活动、气体积累和压力变化共同导致。地幔或地壳深处的岩石部分熔融形成岩浆，岩浆中含有水蒸气、二氧化碳、二氧化硫等挥发性气体。当岩浆上升并使压力持续增大时，岩浆和气体会沿裂隙或火山通道喷出地表。""",
    "为什么会有四季？": """四季变化主要由地球自转轴倾斜和地球绕太阳公转共同造成。地球自转轴相对于公转轨道平面有一定倾角，因此一年中不同时间，太阳直射点会在南北回归线之间移动。某一半球朝向太阳时，太阳高度角更大、白昼更长、接收能量更多，形成夏季；背向太阳时则形成冬季。""",
    "月亮为什么会有阴晴圆缺？": """月亮的阴晴圆缺称为月相变化，原因是月球绕地球运行时，太阳始终照亮月球的一半，而地球上的观察者在不同位置看到的受光部分比例不同。新月时，月球受光面大多背向地球；满月时，受光面大多朝向地球。随着月球位置变化，会出现上弦月、满月、下弦月等月相。""",
    "声音是怎么传播的？": """声音是由物体振动产生的机械波，需要依靠介质传播。物体振动会带动周围空气、水或固体中的粒子发生周期性压缩和稀疏，这种扰动向外传递就形成声波。声音在不同介质中的传播速度不同，通常在固体中较快，在液体中次之，在气体中较慢，在真空中不能传播。""",
    "电流是什么？": """电流是电荷的定向移动。金属导体中的电流主要来自自由电子在电场作用下的定向运动，电解质溶液中的电流可以由正负离子移动形成。电流大小表示单位时间内通过导体横截面的电荷量，单位是安培。电流、电压和电阻之间常用欧姆定律描述。""",
    "熵是什么意思？": """熵是热力学中描述系统微观状态数、无序程度或能量分散程度的物理量。一个系统可实现的微观排列方式越多，熵通常越大。热力学第二定律指出，在孤立系统中，自发过程通常朝着总熵增加的方向进行。熵也常用于解释热传导、气体扩散和能量转化效率。""",
    "黑洞是什么？": """黑洞是一种引力极强的天体区域，其事件视界以内的逃逸速度超过光速，因此连光也无法逃离。黑洞通常可由大质量恒星演化末期坍缩形成，也可能以超大质量形式存在于星系中心。黑洞本身不发光，但周围物质落入黑洞前形成吸积盘时会释放强烈辐射，使其能够被间接观测。""",
    "原子是什么？": """原子是构成普通物质的基本单位之一，由原子核和核外电子组成。原子核包含质子和中子，质子带正电，中子不带电，电子带负电并分布在核外。不同元素由质子数决定，例如氢原子有一个质子，碳原子有六个质子。原子之间可以通过化学键形成分子、晶体和各种材料。"""
}

qa_data.update({
    "比特币是什么？": """比特币是一种基于点对点网络、密码学和工作量证明的数字货币系统。它没有中央银行、单一清算机构或统一服务器，而是由全球节点共同维护一份公开账本。比特币系统的核心包括区块链、UTXO 交易模型、数字签名、哈希函数、工作量证明和经济激励。用户通过私钥控制资金，交易经过签名后广播到网络，由节点验证有效性，再由矿工打包进区块，最终成为链上记录。""",
    "比特币为什么是去中心化的？": """比特币被称为去中心化，是因为它的账本维护、交易验证和区块传播不依赖单一机构。任何人都可以运行全节点，独立保存区块链数据，并按照公开共识规则验证交易和区块。矿工负责竞争出块，但不能随意创造违反规则的比特币或强迫节点接受无效区块。全节点、矿工、用户和开发者之间形成相互制衡，使系统的可信性主要来自公开规则、密码学验证和分布式共识。""",
    "区块链是什么？": """区块链是一种把数据按时间顺序组织成区块，并用哈希指针连接起来的账本结构。每个区块通常包含区块头、前一区块哈希、默克尔根、时间戳、难度相关字段、随机数以及一批交易。由于新区块引用前一区块的哈希值，修改历史区块会破坏后续区块的哈希关系，并需要重新完成大量工作量证明。区块链的价值在于让历史记录可验证、难篡改、可复制和可审计。""",
    "比特币交易是怎么完成的？": """比特币交易是用已有的未花费交易输出作为输入，再创建新的交易输出给接收方或找零地址。用户的钱包会选择合适的 UTXO，构造交易数据，并用对应私钥生成数字签名，证明自己有权花费这些输入。交易广播后，全节点会检查格式、签名、脚本条件、输入是否未花费、金额是否守恒以及手续费是否合理。有效交易进入节点内存池，矿工选择交易打包进区块，区块被网络接受后交易获得确认。""",
    "比特币钱包是什么？": """比特币钱包不是直接存放比特币的容器，而是管理私钥、公钥、地址和交易签名的工具。区块链上记录的是 UTXO，钱包通过扫描链上数据找出属于自己的可花费输出，并用私钥对交易进行签名。钱包可以是软件钱包、硬件钱包、冷钱包或多签钱包。它的核心功能包括生成密钥、备份种子、派生地址、查询余额、构造交易、签名交易和广播交易。""",
    "私钥和公钥有什么区别？": """私钥是用户控制资产或身份的核心秘密数据，必须保密；公钥是由私钥通过椭圆曲线标量乘法推导出的公开数据，可以给别人用于验证签名。私钥可以生成数字签名，证明某笔交易或消息由私钥持有者授权；公钥可以验证签名是否与消息和私钥匹配。安全的非对称密码体系要求从公钥反推出私钥在计算上不可行，因此私钥负责控制权，公钥负责验证。""",
    "比特币地址是什么？": """比特币地址是接收比特币时常用的字符串表示，通常由公钥、公钥哈希或脚本经过编码得到。地址本身不是私钥，也不是账户余额，而是链上输出锁定条件的一种可读形式。向某个地址转账，本质上是在区块链上创建一个满足特定脚本条件才能花费的 UTXO。不同地址格式对应不同脚本类型，例如传统地址、隔离见证地址和 Taproot 地址，它们在编码方式、交易结构和手续费效率上有所不同。""",
    "数字签名是什么？": """数字签名是一种用私钥生成、用公钥验证的密码学机制，用来证明消息来源、授权关系和数据完整性。在比特币中，用户花费某个 UTXO 时，需要对交易的特定摘要生成签名，节点再用对应公钥验证签名是否有效。有效签名说明交易确实由掌握私钥的人授权，并且签名覆盖的交易内容没有被篡改。比特币早期主要使用 ECDSA，Taproot 引入了基于 Schnorr 签名的机制。""",
    "数字签名和加密有什么区别？": """数字签名和加密都属于密码学技术，但目标不同。加密的主要目标是机密性，把明文变成密文，使没有解密密钥的人无法读取内容；数字签名的主要目标是认证、授权和完整性，证明某条消息来自私钥持有者并且没有被篡改。签名不是简单地用私钥加密消息，而是对消息摘要和私钥进行数学运算生成签名值，再由公钥验证。比特币交易使用签名来证明花费权限，而不是用签名隐藏交易内容。""",
    "哈希函数是什么？": """哈希函数是一种把任意长度输入转换成固定长度输出的算法，输出称为哈希值或摘要。密码学哈希函数应具有单向性、抗碰撞性和雪崩效应，也就是难以从哈希值反推出原文，难以找到两个不同输入得到同一哈希值，输入微小变化会导致输出显著变化。比特币使用哈希函数生成交易标识、区块标识、默克尔树节点和工作量证明目标，哈希函数是区块链不可篡改性和高效验证的重要基础。""",
    "工作量证明是什么？": """工作量证明是一种通过计算成本来参与共识的机制。比特币矿工构造候选区块后，需要不断改变 nonce、时间戳或交易组合等可变数据，使区块头哈希值低于当前难度目标。寻找有效哈希需要大量重复计算，但其他节点验证结果非常快。工作量证明使重写历史区块需要重新付出对应计算成本，并追上或超过诚实网络累计工作量，从而提高篡改账本和双花攻击的难度。""",
    "比特币挖矿是什么？": """比特币挖矿是矿工收集交易、构造候选区块、执行工作量证明并争取获得区块奖励的过程。矿工会把普通交易和一笔 coinbase 交易放入区块，coinbase 交易用于领取区块补贴和交易手续费。矿工不断尝试不同区块头数据，使哈希满足难度目标。成功找到有效区块后，矿工把区块广播给网络，其他节点验证无误后接受该区块。挖矿同时承担新区块产生、交易排序、账本安全和发行节奏控制等作用。""",
    "比特币为什么需要确认数？": """确认数表示某笔交易所在区块之后又叠加了多少个新区块。交易刚被打包进区块时通常算一层确认，后续每新增一个有效区块，交易被链重组移除的难度通常都会增加。确认数越多，说明这笔交易越深地嵌入当前累计工作量最高的有效链中，被回滚的概率越低。小额交易可能接受较少确认，大额交易通常等待更多确认，以降低双花或链重组带来的风险。""",
    "双花攻击是什么？": """双花攻击是指攻击者试图把同一笔比特币花费两次。典型方式是先向商家广播一笔付款交易，同时私下构造另一笔把相同输入转回自己的冲突交易。如果攻击者能让包含自己冲突交易的链获得更高累计工作量，原本商家看到的付款交易可能被回滚。比特币通过 UTXO 检查、签名验证、交易冲突规则、工作量证明和确认数来降低双花成功概率，但安全性与攻击者算力比例、等待确认数和交易金额有关。""",
    "UTXO是什么？": """UTXO 是 Unspent Transaction Output 的缩写，意思是未花费交易输出，是比特币记录资金状态的基本单位。比特币没有传统银行式账户余额表，而是用一组尚未被花费的输出表示可用资金。发起交易时，钱包选择若干 UTXO 作为输入，创建新的输出给接收方和找零地址。节点验证交易时，会检查输入引用的 UTXO 是否存在、是否未被花费、脚本和签名是否满足条件，以及输入总额是否不小于输出总额。""",
    "默克尔树是什么？": """默克尔树是一种用哈希值组织大量数据的树形结构。比特币区块中的交易会先分别计算交易哈希，再两两组合继续哈希，最终得到一个默克尔根。默克尔根写入区块头，用一个固定长度哈希值概括整个区块的交易集合。借助默克尔树，轻节点可以通过默克尔证明验证某笔交易是否包含在某个区块中，而不必下载区块内全部交易，因此它提高了数据完整性验证和轻量级验证的效率。""",
    "什么是共识机制？": """共识机制是分布式系统中让多个参与者在没有中心协调者的情况下，对同一份状态或历史记录达成一致的方法。在区块链中，共识机制规定交易怎样被验证，区块怎样产生，冲突链怎样选择，无效区块怎样被拒绝。比特币使用工作量证明和最高累计工作量有效链规则，使节点能够在开放网络中选择同一条历史。共识机制不仅是出块算法，也包括节点执行的交易格式、供应上限、区块规则和脚本验证规则。""",
    "去中心化有什么优点？": """去中心化的优点是系统不依赖单一管理者、单点服务器或单一数据库，因此抗故障、抗审查和开放参与能力更强。任何人都可以独立运行节点验证规则，减少对第三方记账机构的信任依赖。个别节点宕机、被攻击或退出，并不会导致系统整体停止。去中心化还提高了规则透明度和可审计性，因为账本和验证规则可以由用户自行检查，而不是完全依赖某个机构声明。""",
    "去中心化有什么缺点？": """去中心化系统通常要牺牲一部分效率、治理速度和用户体验。由于许多节点需要重复验证和同步数据，吞吐量、延迟和存储成本往往不如中心化数据库。规则升级需要较广泛的生态共识，协调过程复杂且可能产生分歧。用户自行管理私钥也带来责任转移，一旦私钥或助记词丢失，通常无法通过中心客服找回资产；一旦密钥泄露，攻击者可能直接转移资金。""",
    "智能合约是什么？": """智能合约是部署在区块链或类似分布式系统上的程序化规则，可以根据预设条件自动执行状态变化或资产转移。它不是传统法律合同本身，而是把部分业务逻辑写成可验证、可执行的代码。智能合约常用于代币发行、去中心化交易、借贷、治理、托管和自动结算。它的优点是执行过程公开、结果可验证、减少中介依赖；缺点是代码漏洞、预言机错误、权限设计失误和经济攻击可能造成严重损失。""",
    "稳定币是什么？": """稳定币是一类试图让价格锚定某种外部资产的加密资产，常见锚定对象是美元等法定货币。稳定币可以通过法币储备、短期资产储备、加密资产超额抵押或算法调节机制维持价格。它常用于链上支付、交易结算、跨平台转账和 DeFi 应用。稳定币的关键问题包括储备真实性、赎回机制、发行方信用、监管风险、抵押品波动、清算机制和极端市场条件下的脱锚风险。""",
    "加密货币和区块链有什么区别？": """区块链是一种分布式账本结构和状态同步技术，用来记录交易、数据或程序状态；加密货币是区块链上的一种典型应用，用于表示价值、支付手续费或激励网络参与者。比特币既是一种加密货币，也是一个区块链网络。并不是所有区块链都必须发行公开交易的代币，也不是所有数字资产都具备同等程度的去中心化、安全性或抗审查性。""",
    "助记词是什么？": """助记词是一组按照固定词表和校验规则生成的单词，用来更方便地备份和恢复钱包。许多钱包使用 BIP39 类似方案，把随机熵编码成助记词，再从助记词和可选密码短语派生出种子，种子又可用于分层确定性钱包生成大量私钥、公钥和地址。助记词不是普通登录密码，而是恢复钱包控制权的根材料；掌握助记词通常就能恢复并控制对应钱包中的资产。""",
    "硬件钱包是什么？": """硬件钱包是一种把私钥保存在专用硬件设备中的钱包形式。它通常让私钥留在设备内部，交易摘要在设备内签名，外部电脑或手机只负责构造交易、展示信息和广播签名结果。硬件钱包可以降低联网设备中恶意软件直接窃取私钥的风险，并通过屏幕确认地址和金额来减少钓鱼风险。它适合长期保存加密资产，但仍需要正确备份助记词、验证交易信息并防范供应链和社工攻击。""",
    "多签钱包是什么？": """多签钱包是需要多个私钥中的若干个共同授权才能花费资金的钱包结构。例如 2-of-3 多签表示共有三个密钥，任意两个有效签名即可花费资金。多签可以降低单个私钥丢失或被盗造成的风险，也适合企业资金管理、家庭共同保管、托管服务和灾备方案。多签的关键在于合理分散密钥、保存赎回脚本或描述符、测试恢复流程，并避免所有密钥落在同一设备或同一地点。""",
    "公链和联盟链有什么区别？": """公链通常向所有人开放，任何人都可以读取数据、发送交易、运行节点，并在满足规则时参与共识，典型目标是开放性、抗审查性和最小化信任。联盟链通常由一组已知机构共同维护，节点准入、权限、身份和治理规则更受控制，性能、合规和隐私管理更容易优化。两者都可能使用区块链结构，但信任模型不同：公链更依赖开放共识和经济激励，联盟链更依赖参与机构和权限治理。""",
    "对称加密和非对称加密有什么区别？": """对称加密使用同一个密钥进行加密和解密，速度快，适合大量数据加密，但密钥分发和密钥管理是难点。非对称密码使用公钥和私钥两类相关密钥，公钥可以公开，私钥必须保密，常用于数字签名、身份认证和密钥交换。实际安全通信通常结合二者：先用非对称密码完成身份认证和会话密钥协商，再用对称加密或 AEAD 算法高效保护大量通信数据。""",
    "ChaCha20是什么？": """ChaCha20 是一种对称流加密算法，由 256 位密钥、nonce 和计数器生成伪随机密钥流，再把密钥流与明文异或得到密文。它适合软件实现，在许多没有 AES 硬件加速的设备上性能很好。ChaCha20 只提供机密性，也就是让攻击者难以读取明文；它本身不提供完整性和来源认证。如果密钥和 nonce 组合被重复用于不同消息，流加密安全性会受到严重破坏。""",
    "Poly1305是什么？": """Poly1305 是一种消息认证码算法，用于验证数据完整性和真实性。它根据密钥和消息计算一个认证标签，接收方用相同密钥重新计算标签并比较，从而判断消息是否被篡改以及是否来自持有密钥的一方。Poly1305 不负责加密明文，因此不能单独提供机密性。实际协议中常把 Poly1305 与 ChaCha20 组合，由 ChaCha20 生成一次性认证密钥，再由 Poly1305 认证密文和附加数据。""",
    "ChaCha20-Poly1305是什么？": """ChaCha20-Poly1305 是一种 AEAD 认证加密算法，把 ChaCha20 的流加密能力和 Poly1305 的消息认证能力结合起来。ChaCha20 用于加密明文，Poly1305 用于生成认证标签，保护密文和关联数据不被篡改。它可以同时提供机密性、完整性和真实性，常见于 TLS、QUIC、VPN、移动通信和现代安全协议。使用时必须保证同一密钥下 nonce 不重复，否则可能破坏机密性和认证安全。""",
    "AEAD是什么意思？": """AEAD 是 Authenticated Encryption with Associated Data 的缩写，意思是带关联数据的认证加密。它在加密明文的同时，会对密文和附加数据生成认证标签。附加数据不会被加密，但会被完整性保护，例如协议头、版本号、序列号或路由元数据。接收方只有在认证标签验证通过后才应接受解密结果。AEAD 的优点是把加密和认证组合成一个明确接口，减少只加密不认证或认证顺序错误导致的安全问题。""",
    "nonce在加密里是什么意思？": """nonce 是 number used once 的缩写，表示在特定密钥下应当只使用一次的数值。许多加密算法会把 nonce 与密钥、计数器或消息序号结合，确保相同明文在不同 nonce 下产生不同密文。nonce 通常不需要保密，但必须满足算法要求的唯一性或随机性。对 ChaCha20-Poly1305 这类 AEAD 算法来说，同一密钥下重复 nonce 会导致密钥流复用，并可能泄露明文关系或使认证安全失效。""",
    "密钥交换是什么？": """密钥交换是通信双方在不安全网络上协商共享秘密的过程。典型方法包括 Diffie-Hellman 和椭圆曲线 Diffie-Hellman。双方各自生成私有随机数，并交换对应的公开值，通过数学运算得到相同共享秘密；旁观者即使看到公开值，也难以计算出该秘密。协商出的共享秘密通常不会直接作为加密密钥，而是输入 HKDF 等密钥派生函数，生成用于 AEAD 加密、消息认证和会话保护的密钥材料。""",
    "X25519是什么？": """X25519 是基于 Curve25519 的椭圆曲线 Diffie-Hellman 密钥交换算法，用于让通信双方协商共享秘密。它不是加密算法，也不是数字签名算法，而是密钥协商算法。X25519 具有实现简单、性能好、抗部分实现错误能力较强等特点，常用于 TLS、WireGuard、Signal 等现代安全协议。实际系统通常会把 X25519 得到的共享秘密输入密钥派生函数，再派生出对称加密密钥。""",
    "Ed25519是什么？": """Ed25519 是一种基于 Edwards 曲线的数字签名算法，用于身份认证、消息完整性验证和授权证明。它和 X25519 都与 Curve25519 家族有关，但用途不同：X25519 用于密钥交换，Ed25519 用于数字签名。Ed25519 签名速度快、签名短、验证效率高，并且在现代协议和软件供应链签名中很常见。使用时需要保护私钥，并确保实现正确处理消息编码、随机性或确定性签名流程。""",
    "端到端加密是什么？": """端到端加密是指消息在发送端加密，并且只有预期接收端能够解密，中间服务器、网络运营商或转发节点无法读取明文内容。它通常结合身份密钥、密钥交换、会话密钥、AEAD、消息认证码和密钥轮换机制实现。端到端加密可以保护通信内容免受中间节点读取或篡改，但不能自动隐藏所有元数据，例如通信双方、时间、频率和消息大小，也不能替代终端设备本身的安全防护。""",
    "零知识证明是什么？": """零知识证明是一种密码学协议，允许证明者向验证者证明某个陈述为真，同时不泄露除陈述真实性以外的额外信息。例如，证明者可以证明自己知道某个秘密，或证明某笔交易满足余额和规则约束，而不公开秘密或完整交易细节。零知识证明常用于隐私保护、身份认证、区块链扩容、有效性证明和合规证明。常见系统会关注完备性、可靠性、零知识性、证明大小、验证速度和可信设置等问题。""",
    "哈希承诺是什么？": """哈希承诺是一种用哈希函数实现的承诺机制。承诺方先把秘密数据和随机盐一起计算哈希值并公开，这相当于先锁定一个选择；之后再公开原始数据和随机盐，验证者重新计算哈希值即可确认承诺是否一致。哈希承诺具有隐藏性和绑定性：公开哈希时别人难以知道秘密内容，但承诺方之后也难以改成另一个内容。它常用于抽签、投票、协议协商和区块链交互。""",
    "随机数在密码学里为什么重要？": """随机数在密码学中非常重要，因为密钥生成、nonce、签名、密钥交换和挑战响应都可能依赖不可预测的数据。高质量随机数可以防止攻击者猜出密钥、重放协议或恢复私钥。随机数质量不足会导致严重漏洞，例如重复签名随机数可能泄露数字签名私钥，重复流加密 nonce 可能泄露明文关系。密码学系统通常需要使用安全随机数生成器，而不是普通伪随机函数或时间戳。""",
    "哈希和加密有什么区别？": """哈希和加密的目标不同。哈希是单向摘要函数，把任意长度输入变成固定长度输出，通常不能从哈希值还原原文，常用于完整性校验、索引、承诺和工作量证明。加密是可逆变换，把明文变成密文，持有正确密钥的人可以解密还原明文。哈希不需要解密密钥，而加密依赖密钥保护机密性。密码系统中经常同时使用哈希、加密、签名和消息认证码，但它们承担的安全目标不同。"""
})
model = SentenceTransformer("sentence-transformers/paraphrase-multilingual-mpnet-base-v2")
questions = list(qa_data.keys())
vectors = model.encode(
    questions,
    convert_to_numpy=True,
    normalize_embeddings=True
).astype("float32")
dim = vectors.shape[1]
index = faiss.IndexFlatIP(dim)
# 插入数据
index.add(vectors)
def search(query, top_k=1):
    query_vector = model.encode(
        [query],
        convert_to_numpy=True,
        normalize_embeddings=True
    ).astype("float32")
    scores, ids = index.search(query_vector, top_k)
    idx = ids[0][0]
    score = scores[0][0]
    matched_question = questions[idx]
    answer = qa_data[matched_question]
    return answer, matched_question, float(score)


while True:
    query = input("请输入问题，输入 q 退出：").strip()
    if query.lower() in ["q", "quit", "exit"]:
        break
    answer, matched_question, score = search(query)
    print("回答：", answer)
    print("匹配问题：", matched_question)
    print("相似度：", score)
    print()
